import type { PaymentAccountStatus } from '~/client';

interface BranchData {
  title?: string | null;
  statusLabel?: string | null;
  textStatus: string;
  textStatusClass?: string;
  description?: string | null;
  branchUrl: string;
  transactionsButton?: boolean;
  branchLogoBgClass?: string;
}

export const branchData: Record<PaymentAccountStatus, BranchData | null> = {
  activated: {
    title: 'Payment information',
    statusLabel: 'Branch Payment Profile:',
    textStatus: 'Active',
    textStatusClass: 'text-success-foreground',
    description: 'Fast, secure payouts to selected payment method',
    branchUrl: 'https://www.branchapp.com/',
    transactionsButton: true,
    branchLogoBgClass: 'fill-success-foreground',
  },
  deactivated: {
    title: 'Payment information',
    statusLabel: 'Unable to send payouts',
    textStatus: '',
    description: 'Please check your Branch payment profile.',
    branchUrl: 'https://www.branchapp.com/',
    branchLogoBgClass: 'fill-destructive',
  },
  not_registered: null,
  registered: {
    title: 'Payment information',
    statusLabel: 'Branch:',
    textStatus: 'Action Required',
    description: 'Visit Branch to select your payment method',
    branchUrl: 'https://www.branchapp.com/',
    branchLogoBgClass: 'fill-warning-foreground',
  },
};

export const getBranchDataByStatus = (status: PaymentAccountStatus, branchUrl?: string | null): BranchData | null => {
  const data = branchData[status];
  if (!data) return null;
  return branchUrl ? { ...data, branchUrl } : { ...data };
};
